module crc8_serial_engine_fix(
    input  logic       clk,
    input  logic       rst_n,
    input  logic       init,
    input  logic       din,
    output logic [7:0] crc_out
);
    logic fb;
    assign fb = crc_out[7] ^ din;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            crc_out <= 8'h00;
        end else if (init) begin
            crc_out <= 8'h00;
        end else begin
            // BUG: inverted feedback logic!
            if (!fb) begin
                crc_out <= {crc_out[6:0], 1'b0} ^ 8'h07;
            end else begin
                crc_out <= {crc_out[6:0], 1'b0};
            end
        end
    end
endmodule

