module fifo_underflow_guard_fix(
    input  logic       clk,
    input  logic       rst_n,
    input  logic       wr_en,
    input  logic       rd_en,
    output logic [3:0] count,
    output logic       underflow_err
);
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 4'd0;
            underflow_err <= 1'b0;
        end else begin
            // BUG: unconditionally decrements count on rd_en without checking count > 0!
            if (rd_en && (count == 4'd0)) begin
                underflow_err <= 1'b1;
                count <= count - 4'd1; // BUG!
            end else if (rd_en && !wr_en) begin
                underflow_err <= 1'b0;
                count <= count - 4'd1;
            end else if (wr_en && !rd_en && (count < 4'd8)) begin
                underflow_err <= 1'b0;
                count <= count + 4'd1;
            end else begin
                underflow_err <= 1'b0;
            end
        end
    end
endmodule

