module rr_mask_arbiter_fix(
    input  logic       clk,
    input  logic       rst_n,
    input  logic [3:0] req,
    output logic [3:0] grant
);
    logic [1:0] ptr;
    logic [3:0] mask;
    logic [3:0] masked_req;

    always_comb begin
        case (ptr)
            2'd0: mask = 4'b1110;
            2'd1: mask = 4'b1100;
            2'd2: mask = 4'b1000;
            2'd3: mask = 4'b0000;
        endcase
        masked_req = req & mask;
    end

    // BUG: Checks raw req BEFORE checking masked_req!
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ptr <= 2'd0;
            grant <= 4'd0;
        end else begin
            if (|req) begin // BUG: should check |masked_req first!
                if (masked_req[0]) begin grant <= 4'b0001; ptr <= 2'd0; end
                else if (masked_req[1]) begin grant <= 4'b0010; ptr <= 2'd1; end
                else if (masked_req[2]) begin grant <= 4'b0100; ptr <= 2'd2; end
                else if (masked_req[3]) begin grant <= 4'b1000; ptr <= 2'd3; end
                else if (req[0]) begin grant <= 4'b0001; ptr <= 2'd0; end
                else if (req[1]) begin grant <= 4'b0010; ptr <= 2'd1; end
                else if (req[2]) begin grant <= 4'b0100; ptr <= 2'd2; end
                else if (req[3]) begin grant <= 4'b1000; ptr <= 2'd3; end
            end else begin
                grant <= 4'd0;
            end
        end
    end
endmodule

