module quad_decoder_seq_fix(
    input  logic       clk,
    input  logic       rst_n,
    input  logic [1:0] ab,
    output logic [7:0] pos,
    output logic       dir
);
    logic [1:0] last_ab;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pos <= 8'd0;
            dir <= 1'b0;
            last_ab <= 2'b00;
        end else begin
            last_ab <= ab;
            case ({last_ab, ab})
                4'b00_01, 4'b01_11, 4'b11_10, 4'b10_00: begin
                    pos <= pos + 8'd1;
                    dir <= 1'b1;
                end
                // BUG: 4'b11_01 is reverse (-1), but here it was placed in forward or omitted!
                4'b00_10, 4'b10_11, 4'b01_00: begin
                    pos <= pos - 8'd1;
                    dir <= 1'b0;
                end
                4'b11_01: begin
                    pos <= pos + 8'd1; // BUG! Should be pos - 1
                    dir <= 1'b1;
                end
                default: begin
                    pos <= pos;
                    dir <= dir;
                end
            endcase
        end
    end
endmodule

